{"code": "import sqlite3, json, sys

db_path = "/home/liangfeng/git/hermes-agent/benchmark/skillsbench/tasks/civ6-adjacency-optimizer/environment/data/maps/e2e_test_case_0.Civ6Map"
conn = sqlite3.connect(db_path)
conn.row_factory = sqlite3.Row
cursor = conn.cursor()

# Map dimensions
cursor.execute("SELECT Width, Height FROM Map LIMIT 1")
row = cursor.fetchone()
width, height = row["Width"], row["Height"]
print(f"Map: {width} x {height}")

TERRAIN_MAP = {
    "TERRAIN_COAST": "COAST", "TERRAIN_OCEAN": "OCEAN",
    "TERRAIN_GRASS": "GRASS", "TERRAIN_GRASS_HILLS": "GRASS",
    "TERRAIN_GRASS_MOUNTAIN": "MOUNTAIN", "TERRAIN_PLAINS": "PLAINS",
    "TERRAIN_PLAINS_HILLS": "PLAINS", "TERRAIN_PLAINS_MOUNTAIN": "MOUNTAIN",
    "TERRAIN_DESERT": "DESERT", "TERRAIN_DESERT_HILLS": "DESERT",
    "TERRAIN_DESERT_MOUNTAIN": "MOUNTAIN", "TERRAIN_TUNDRA": "TUNDRA",
    "TERRAIN_TUNDRA_HILLS": "TUNDRA", "TERRAIN_TUNDRA_MOUNTAIN": "MOUNTAIN",
    "TERRAIN_SNOW": "SNOW", "TERRAIN_SNOW_HILLS": "SNOW",
    "TERRAIN_SNOW_MOUNTAIN": "MOUNTAIN",
}

NATURAL_WONDERS = {
    "FEATURE_BARRIER_REEF", "FEATURE_CLIFFS_DOVER", "FEATURE_CRATER_LAKE",
    "FEATURE_DEAD_SEA", "FEATURE_EVEREST", "FEATURE_GALAPAGOS",
    "FEATURE_KILIMANJARO", "FEATURE_PANTANAL", "FEATURE_PIOPIOTAHI",
    "FEATURE_TORRES_DEL_PAINE", "FEATURE_TSINGY", "FEATURE_YOSEMITE",
    "FEATURE_ULURU", "FEATURE_DELICATE_ARCH", "FEATURE_EYE_OF_THE_SAHARA",
    "FEATURE_LAKE_RETBA", "FEATURE_MATTERHORN", "FEATURE_RORAIMA",
    "FEATURE_UBSUNUR_HOLLOW", "FEATURE_ZHANGYE_DANXIA", "FEATURE_HA_LONG_BAY",
    "FEATURE_EYJAFJALLAJOKULL", "FEATURE_LYSEFJORDEN", "FEATURE_GIANTS_CAUSEWAY",
}

RESOURCE_TYPE_MAP = {
    "RESOURCE_HORSES": "STRATEGIC", "RESOURCE_IRON": "STRATEGIC",
    "RESOURCE_NITER": "STRATEGIC", "RESOURCE_COAL": "STRATEGIC",
    "RESOURCE_OIL": "STRATEGIC", "RESOURCE_ALUMINUM": "STRATEGIC",
    "RESOURCE_URANIUM": "STRATEGIC",
    "RESOURCE_DIAMONDS": "LUXURY", "RESOURCE_PEARLS": "LUXURY",
    "RESOURCE_JADE": "LUXURY", "RESOURCE_MARBLE": "LUXURY",
    "RESOURCE_SILK": "LUXURY", "RESOURCE_SPICES": "LUXURY",
    "RESOURCE_SUGAR": "LUXURY", "RESOURCE_TEA": "LUXURY",
    "RESOURCE_TOBACCO": "LUXURY", "RESOURCE_WINE": "LUXURY",
    "RESOURCE_WHALES": "LUXURY", "RESOURCE_COTTON": "LUXURY",
    "RESOURCE_FISH": "BONUS", "RESOURCE_WHEAT": "BONUS",
    "RESOURCE_CATTLE": "BONUS", "RESOURCE_SHEEP": "BONUS",
    "RESOURCE_DEER": "BONUS", "RESOURCE_BANANAS": "BONUS",
    "RESOURCE_RICE": "BONUS", "RESOURCE_MAIZE": "BONUS",
    "RESOURCE_STONE": "BONUS", "RESOURCE_COPPER": "BONUS",
}

NATURAL_WONDERS2 = {"RESOURCE_ULURU", "RESOURCE_FOUNTAIN_OF_YOUTH", "RESOURCE_GRAND_MESA", "RESOURCE_BARRIER_REEF", "RESOURCE_LYSEFJORD"}

cursor.execute("PRAGMA table_info(Plots)")
columns = {col["name"] for col in cursor.fetchall()}
print(f"Plots columns: {sorted(columns)}")

# Build tile data
tiles = {}
cursor.execute("SELECT * FROM Plots")
for row in cursor.fetchall():
    plot_id = row["ID"]
    x = plot_id % width
    y = plot_id // width
    raw = row["TerrainType"] or ""
    terrain = TERRAIN_MAP.get(raw, raw.replace("TERRAIN_", ""))
    is_hills = "_HILLS" in raw

    tile = {"x": x, "y": y, "terrain": terrain}
    if is_hills:
        tile["is_hills"] = True
    tiles[(x, y)] = tile

# Add rivers
cursor.execute("PRAGMA table_info(PlotRivers)")
river_cols = {col["name"] for col in cursor.fetchall()}
try:
    cursor.execute("SELECT * FROM PlotRivers")
    for row in cursor.fetchall():
        plot_id = row["PlotID"] if "PlotID" in river_cols else row["ID"]
        x, y = plot_id % width, plot_id // width
        tile = tiles.get((x, y))
        if not tile:
            continue
        river_edges = []
        row_d = dict(row)
        if row_d.get("IsNEOfRiver"): river_edges.append(1)
        if row_d.get("IsNWOfRiver"): river_edges.append(2)
        if row_d.get("IsWOfRiver"): river_edges.append(3)
        if row_d.get("EFlowDirection", -1) != -1: river_edges.append(0)
        if row_d.get("SWFlowDirection", -1) != -1: river_edges.append(4)
        if row_d.get("SEFlowDirection", -1) != -1: river_edges.append(5)
        if river_edges:
            tile["river_edges"] = sorted(river_edges)
except Exception as e:
    print(f"River error: {e}")

# Add resources
try:
    cursor.execute("SELECT * FROM PlotResources")
    for row in cursor.fetchall():
        plot_id = row["PlotID"] if "PlotID" in dict(row).keys() else row["ID"]
        x, y = plot_id % width, plot_id // width
        tile = tiles.get((x, y))
        if tile:
            res = row["ResourceType"]
            if res in NATURAL_WONDERS2:
                tile["is_natural_wonder"] = True
            else:
                tile["resource"] = res
                tile["resource_type"] = RESOURCE_TYPE_MAP.get(res, "BONUS")
except Exception as e:
    print(f"Resource error: {e}")

# Add features from Plots
try:
    cursor.execute("SELECT * FROM Plots")
    feat_count = 0
    for row in cursor.fetchall():
        raw_feature = row.get("FeatureType")
        if not raw_feature:
            continue
        plot_id = row["ID"]
        x, y = plot_id % width, plot_id // width
        tile = tiles.get((x, y))
        if tile and raw_feature:
            if raw_feature in NATURAL_WONDERS:
                tile["feature"] = raw_feature
                tile["is_natural_wonder"] = True
            else:
                tile["feature"] = raw_feature
            if "FLOODPLAINS" in raw_feature:
                tile["is_floodplains"] = True
except Exception as e:
    print(f"Feature error: {e}")

# Print tiles in a grid around city center (22, 15) with radius 3
CX, CY = 22, 15
print(f"\nTile grid around ({CX},{CY}):")
print("=" * 80)
for y_offset in range(-3, 4):
    for x_offset in range(-3, 4):
        tx, ty = CX + x_offset, CY + y_offset
        tile = tiles.get((tx, ty))
        if not tile:
            sym = "?"
        else:
            t = tile["terrain"]
            if t == "MOUNTAIN": sym = "M"
            elif t in ("COAST", "OCEAN", "LAKE"): sym = "~"
            elif tile.get("is_hills"):
                sym = "h" if t == "GRASS" else "H"
            else:
                sym = "." if t == "GRASS" else ("g" if t == "PLAINS" else t[0].lower())
            if tile.get("feature") == "FEATURE_FOREST": sym = sym.upper() + "f"
            if tile.get("feature") == "FEATURE_JUNGLE": sym += "j"
            if tile.get("is_floodplains"): sym += "+"
            if tile.get("resource_type") == "STRATEGIC": sym += "S"
            elif tile.get("resource_type") == "LUXURY": sym += "L"
            if tile.get("river_edges"): sym += "r"

        if (tx, ty) == (CX, CY):
            print(f"X{sym:5s}", end="")
        else:
            print(f"{sym:6s}", end="")
    print()

print()
print(f"\nDetailed tiles around ({CX},{CY}) radius 3:")
for y_offset in range(-3, 4):
    for x_offset in range(-3, 4):
        tx, ty = CX + x_offset, CY + y_offset
        tile = tiles.get((tx, ty))
        if not tile:
            print(f"  ({tx},{ty}): None")
        else:
            info = []
            info.append(f"terrain={tile['terrain']}")
            if tile.get('is_hills'): info.append("hills")
            if tile.get('feature'): info.append(f"feature={tile['feature']}")
            if tile.get('is_floodplains'): info.append("floodplains")
            if tile.get('river_edges'): info.append(f"rivers={tile['river_edges']}")
            if tile.get('resource'): info.append(f"res={tile['resource']}({tile.get('resource_type','')})")
            if tile.get('is_natural_wonder'): info.append("NATURAL_WONDER")
            print(f"  ({tx},{ty}): {', '.join(info)}")

conn.close()
"}

