{"content": "/* style.css - Stock Visualization Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    background: #f4f6f8;
    color: #333;
    padding: 20px;
}

.container {
    display: flex;
    flex-direction: row;
    gap: 20px;
    max-width: 1600px;
    margin: 0 auto;
}

.chart-section {
    flex: 1;
    min-width: 600px;
}

.table-section {
    flex: 0 0 480px;
    max-height: 800px;
    overflow-y: auto;
}

h1 {
    text-align: center;
    margin-bottom: 20px;
    color: #1a1a2e;
    font-size: 24px;
}

svg {
    width: 100%;
    background: #fff;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.tooltip {
    position: absolute;
    background: rgba(0, 0, 0, 0.85);
    color: #fff;
    padding: 8px 12px;
    border-radius: 6px;
    font-size: 13px;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s;
    max-width: 300px;
    z-index: 1000;
}

.tooltip.visible {
    opacity: 1;
}

.tooltip .ticker {
    font-weight: bold;
    font-size: 15px;
}

.tooltip .name {
    margin-top: 3px;
    font-size: 13px;
}

.tooltip .sector {
    margin-top: 3px;
    color: #aaa;
    font-size: 12px;
}

.legend {
    display: flex;
    justify-content: center;
    gap: 16px;
    margin-top: 12px;
    flex-wrap: wrap;
}

.legend-item {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 14px;
}

.legend-color {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    border: 1px solid rgba(0,0,0,0.2);
}

table {
    width: 100%;
    border-collapse: collapse;
    background: #fff;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

thead {
    position: sticky;
    top: 0;
