{"content": "// visualization.js — D3.js v6 Bubble Chart + Data Table + Interactive Linking

(function () {
  'use strict';

  // ─── Sector colour map (5 sectors) ────────────────────────────────────────
  const sectorColors = {
    'Energy':               '#e74c3c',
    'Financial':            '#3498db',
    'Industry':             '#2ecc71',
    'Information Technology': '#9b59b6',
    'ETF':                  '#95a5a6'
  };
  const sectorOrder = ['Energy', 'Financial', 'Industry', 'Information Technology', 'ETF'];

  // ─── Config ───────────────────────────────────────────────────────────────
  const width  = 750;
  const height = 700;
  const radiusScale = d3.scaleSqrt();  // set domain / range after loading data

  // ─── Tooltip ──────────────────────────────────────────────────────────────
  const tooltip = d3.select('body')
    .append('div')
    .attr('class', 'tooltip')
    .attr('id', 'tooltip');

  function showTooltip(event, d) {
    tooltip
      .classed('visible', true)
      .html(
        `<div class="ticker">${d.ticker}</div>` +
        `<div class="name">${d.fullname}</div>` +
        `<div class="sector">Sector: ${d.sector}</div>`
      )
      .style('left', (event.pageX + 14) + 'px')
      .style('top',  (event.pageY - 14) + 'px');
  }

  function hideTooltip() {
    tooltip.classed('visible', false);
  }

  // ─── Format market cap as readable string ─────────────────────────────────
  function formatMarketCap(v) {
    if (v == null || v === '' || isNaN(v)) return 'N/A';
    const n = +v;
    if (n >= 1e12) return (n / 1e12).toFixed(2).replace(/\.?0+$/, '') + 'T';
    if (n >= 1e9)  return (n / 1e9).toFixed(2).replace(/\.?0+$/, '') + 'B';
    if (n >= 1e6)  return (n / 1e6).toFixed(2).replace(/\.?0+$/, '') + 'M';
    if (n >= 1e3)  return (n / 1e3).toFixed(2).replace(/\.?0+$/, '') + 'K';
    return n.toString();
  }

  // ─── Highlight helper (bubble ↔ table) ────────────────────────────────────
  function highlightRow(ticker) {
    d3.selectAll('table tbody tr').classed('highlighted selected', false);
    const row = d3.select(`table tbody tr[data-ticker="${ticker}"]`);
    if (!row.empty()) row.classed('highlighted selected', true);
  }

  function highlightBubble(ticker) {
    d3.selectAll('svg circle.bubble')
      .attr('stroke', null)
      .attr('stroke-width', null);
    d3.selectAll('svg circle.bubble')
      .filter(d => d.ticker === ticker)
      .attr('stroke', '#1a1a2e')
      .attr('stroke-width', 3);
  }

  function clearHighlights() {
    d3.selectAll('table tbody tr').classed('highlighted selected', false);
    d3.selectAll('svg circle.bubble')
      .attr('stroke', null)
      .attr('stroke-width', null);
  }

  // ─── Load data and build everything ───────────────────────────────────────
  const descPath = './data/stock-descriptions.csv';

  d3.csv(descPath).then(function (stocks) {
    // ── parse / clean ────────────────────────────────────────────────────
    const data = stocks.map(function (d) {
      return {
        ticker: d.ticker.trim(),
        sector: d.sector.trim(),
        fullname: d['full name'].trim(),
        marketCap: d.marketCap ? +d.marketCap : null
      };
    });

    // ── Radius scale ─────────────────────────────────────────────────────
    const nonEtf = data.filter(function (d) { return d.sector !== 'ETF' && d.marketCap != null; });
    const mcMin = d3.min(nonEtf, function (d) { return d.marketCap; });
    const mcMax = d3.max(nonEtf, function (d) { return d.marketCap; });
    const etfRadius = 14;   // uniform size for ETFs
    radiusScale.domain([mcMin, mcMax]).range([10, 42]);

    // assign radius
    data.forEach(function (d) {
      if (d.sector === 'ETF' || d.marketCap == null) {
        d.radius = etfRadius;
      } else {
        d.radius = radiusScale(d.marketCap);
      }
      d.color = sectorColors[d.sector] || '#ccc';
    });

    // ── SVG ──────────────────────────────────────────────────────────────
    const svg = d3.select('.chart-section')
      .append('svg')
      .attr('width', width)
      .attr('height', height);

    const g = svg.append('g');

    // ── Force simulation ─────────────────────────────────────────────────
    // Compute cluster centres: spread 5 sectors across the canvas nicely
    const cx = width / 2;
    const cy = height / 2;
    const clusterR = 180;  // radius from center for cluster centres
    const clusterCenters = {};
    sectorOrder.forEach(function (sec, i) {
      const angle = (i / sectorOrder.length) * 2 * Math.PI - Math.PI / 2;
      clusterCenters[sec] = {
        x: cx + clusterR * Math.cos(angle),
        y: cy + clusterR * Math.sin(angle)
      };
    });

    const simulation = d3.forceSimulation(data)
      .force('x', d3.forceX(function (d) { return clusterCenters[d.sector].x; }).strength(0.55))
      .force('y', d3.forceY(function (d) { return clusterCenters[d.sector].y; }).strength(0.55))
      .force('collide', d3.forceCollide(function (d) { return d.radius + 2; }).strength(0.85))
      .force('center', d3.forceCenter(cx, cy).strength(0.04))
      .on('tick', ticked);

    // ── Draw bubbles ─────────────────────────────────────────────────────
    const circles = g.selectAll('circle.bubble')
      .data(data)
      .join('circle')
      .attr('class', 'bubble')
      .attr('r', function (d) { return d.radius; })
      .attr('fill', function (d) { return d.color; })
      .attr('opacity', 0.88)
      .style('cursor', 'pointer')
      // ETF bubbles: no tooltip
      .on('mouseover', function (event, d) {
        if (d.sector === 'ETF') return;   // no tooltip for ETF
        d3.select(this).attr('opacity', 1);
        showTooltip(event, d);
      })
      .on('mousemove', function (event, d) {
        if (d.sector === 'ETF') return;
        tooltip
          .style('left', (event.pageX + 14) + 'px')
          .style('top',  (event.pageY - 14) + 'px');
      })
      .on('mouseout', function (event, d) {
        if (d.sector === 'ETF') return;
        d3.select(this).attr('opacity', 0.88);
        hideTooltip();
      })
      .on('click', function (event, d) {
        event.stopPropagation();
        highlightRow(d.ticker);
        d3.selectAll('svg circle.bubble')
          .attr('stroke', null)
          .attr('stroke-width', null);
        d3.select(this).attr('stroke', '#1a1a2e').attr('stroke-width', 3);
      });

    // ── Tick handler ─────────────────────────────────────────────────────
    function ticked() {
      circles
        .attr('cx', function (d) { return d.x; })
        .attr('cy', function (d) { return d.y; });
      // ticker labels
      labels
        .attr('x', function (d) { return d.x; })
        .attr('y', function (d) { return d.y; });
    }

    // ── Ticker labels ────────────────────────────────────────────────────
    const labels = g.selectAll('text.bubble-label')
      .data(data)
      .join('text')
      .attr('class', 'bubble-label')
      .attr('text-anchor', 'middle')
      .attr('dy', '0.35em')
      .attr('fill', '#fff')
      .attr('font-size', '11px')
      .attr('font-weight', '600')
      .attr('pointer-events', 'none')
      .text(function (d) { return d.ticker; });

    // ── Legend ───────────────────────────────────────────────────────────
    const legend = d3.select('.chart-section')
      .append('div')
      .attr('class', 'legend')
      .attr('id', 'legend');

    sectorOrder.forEach(function (sec) {
      const item = legend.append('div').attr('class', 'legend-item');
      item.append('div')
        .attr('class', 'legend-color')
        .style('background-color', sectorColors[sec]);
      item.append('span').text(sec);
    });

    // ── Build data table ─────────────────────────────────────────────────
    const tableContainer = d3.select('.table-section');
    const table = tableContainer.append('table');

    const thead = table.append('thead').append('tr');
    ['Ticker symbol', 'Full company name', 'Sector', 'Market cap'].forEach(function (h) {
      thead.append('th').text(h);
    });

    const tbody = table.append('tbody');

    data.forEach(function (d) {
      const tr = tbody.append('tr')
        .attr('data-ticker', d.ticker)
        .on('mouseover', function () { highlightBubble(d.ticker); })
        .on('mouseout', function () { clearHighlights(); })
        .on('click', function () {
          highlightBubble(d.ticker);
          clearHighlights();
          highlightRow(d.ticker);
        });
      tr.append('td').text(d.ticker);
      tr.append('td').text(d.fullname);
      tr.append('td').text(d.sector);
      tr.append('td').text(formatMarketCap(d.marketCap));
    });

  }).catch(function (err) {
    console.error('Failed to load stock data:', err);
  });
})();
