# Annual values have format like "1973." or "1974." (ending with period)
# 2024 only has partial quarters: I., II., III p. (no "2024." annual entry)

def extract_annual_values(df, year_col=0, value_col=1):
    """Extract annual values. For years without annual entry (like 2024), average quarters."""
    annual_data = {}

    for i in range(len(df)):
        yr_raw = str(df.iloc[i, year_col]).strip()
        val = df.iloc[i, value_col]

        # Skip non-numeric rows
        try:
            float(val)
        except (ValueError, TypeError):
            continue

        # Check if this is a quarter label (contains ":" like "2024: I." or "    II.")
        if ':' in yr_raw:
            # Quarter label like "2024: I."
            year_str = yr_raw.split(':')[0].strip()
            try:
                year = int(year_str)
            except ValueError:
                continue
            if year not in annual_data:
                annual_data[year] = []
            annual_data[year].append(float(val))
        elif '.' in yr_raw and yr_raw.replace('.', '').replace(' ', '').replace('p', '').isdigit():
            # Annual label like "1973." or "1974. " or "1993."
            year_str = yr_raw.replace('.', '').replace(' ', '').replace('p', '')
            try:
                year = int(year_str)
            except ValueError:
                continue
            # This is an annual value - use it directly
            annual_data[year] = float(val)

    return annual_data

