{"code": "import pandas as pd
import numpy as np
import re

# Load data
pce_df = pd.read_excel("/home/liangfeng/git/hermes-agent/benchmark/skillsbench/tasks/econ-detrending-correlation/environment/ERP-2025-table10.xls")
pfi_df = pd.read_excel("/home/liangfeng/git/hermes-agent/benchmark/skillsbench/tasks/econ-detrending-correlation/environment/ERP-2025-table12.xls")
cpi_df = pd.read_excel("/home/liangfeng/git/hermes-agent/benchmark/skillsbench/tasks/econ-detrending-correlation/environment/CPI.xlsx")

# Parse row 0 (year) to determine if it is annual or quarterly
def parse_year_label(raw):
    """Return (year, is_quarter) or None if not a year label."""
    raw = str(raw).strip()

    # Check for quarter labels like "2024: I." or "    II."
    if ':' in raw:
        year_str = raw.split(':')[0].strip()
        try:
            return (int(year_str), True)
        except ValueError:
            return None

    # Check for annual labels like "1973." or "1974. "
    # Must be a number followed by a period
    m = re.match(r'^(\d{4})\.\s*(p\s*)?$', raw)
    if m:
        return (int(m.group(1)), False)

    # Check for quarter continuation labels like "    II." (indented quarters)
    m = re.match(r'^\s+\w+\.\s*$', raw)
    if m:
        # This is a quarter continuation - but we need the year from context
        # These shouldn't appear in the data after proper parsing
        return None

    return None

def extract_series(df, year_col=0, value_col=1):
    """Extract annual time series. Annual entry takes priority over quarters."""
    annual_values = {}  # year -> float (annual value)
    quarter_values = {}  # year -> [list of quarterly values]

    for i in range(len(df)):
        raw = str(df.iloc[i, year_col]).strip()
        val = df.iloc[i, value_col]

        try:
            val_float = float(val)
        except (ValueError, TypeError):
            continue

        parsed = parse_year_label(df.iloc[i, year_col])
        if parsed is None:
            continue

        year, is_quarter = parsed

        if is_quarter:
            if year not in quarter_values:
                quarter_values[year] = []
            quarter_values[year].append(val_float)
        else:
            annual_values[year] = val_float

    # Merge: annual takes priority, otherwise average quarters
    result = {}
    all_years = sorted(set(annual_values.keys()) | set(quarter_values.keys()))
    for year in all_years:
        if year in annual_values:
            result[year] = annual_values[year]
        elif year in quarter_values:
            result[year] = float(np.mean(quarter_values[year]))

    return result

pce_annual = extract_series(pce_df)
pfi_annual = extract_series(pfi_df)

print("PCE annual values:")
for y in sorted(pce_annual.keys()):
    print(f"  {y}: {pce_annual[y]}")

print(f"\nPFI annual values:")
for y in sorted(pfi_annual.keys()):
    print(f"  {y}: {pfi_annual[y]}")

# Check year ranges
print(f"\nPCE years: {min(pce_annual.keys())} to {max(pce_annual.keys())} ({len(pce_annual)} data points)")
print(f"PFI years: {min(pfi_annual.keys())} to {max(pfi_annual.keys())} ({len(pfi_annual)} data points)")"}

