    for attempt in range(max_retries):
        try:
            if attempt > 0:
                time.sleep(0.2 * attempt)

            compounds = pcp.get_compounds(name, 'name')

            if not compounds:
                return (name, None, "Not found in PubChem")

            smiles = compounds[0].smiles
            mol = Chem.MolFromSmiles(smiles)

            if not mol:
                return (name, None, "Invalid SMILES")

            fp = AllChem.GetMorganFingerprint(mol, 2, useChirality=True)
            similarity = DataStructs.TanimotoSimilarity(target_fp, fp)

            return (name, similarity, None)

        except Exception as e:
            error_str = str(e)
            if "Timeout" in error_str or "504" in error_str or "503" in error_str:
                continue
            else:
                return (name, None, error_str)

    return (name, None, "Failed after retries")", "new_string": "def process_molecule(name, target_fp, max_retries=5):
    """
    Process a single molecule: lookup in PubChem and calculate similarity.
    Returns (name, similarity, error) tuple. Uses exponential backoff for retries.
    """
    import time
    import random

    for attempt in range(max_retries):
        try:
            if attempt > 0:
                delay = 0.5 * (attempt + 1) + random.uniform(0, 0.5)
                time.sleep(delay)

            compounds = pcp.get_compounds(name, 'name')

            if not compounds:
                return (name, None, "Not found in PubChem")

            smiles = compounds[0].smiles
            mol = Chem.MolFromSmiles(smiles)

            if not mol:
                return (name, None, "Invalid SMILES")

            fp = AllChem.GetMorganFingerprint(mol, 2, useChirality=True)
            similarity = DataStructs.TanimotoSimilarity(target_fp, fp)

            return (name, similarity, None)

        except Exception as e:
            error_str = str(e)
            # Retry on timeout and server errors
            if any(kw in error_str for kw in ["Timeout", "504", "503", "502", "UNEXPECTED_EOF", "SSL"]):
                continue
            else:
                return (name, None, error_str)

    return (name, None, "Failed after retries")"}

