                    (t - lastShiftTime) > 1 ||
                    (t - windowStart) > 5;
                if (newWindow) {
                    currentWindowScore = 0;
                    windowStart = t;
                }
                currentWindowScore += entry.value;
                lastShiftTime = t;
                if (currentWindowScore > window.__cls) {
                    window.__cls = currentWindowScore;
                }
            }
        }).observe({ type: 'layout-shift', buffered: true });
