def substring_keyword_match(entry: Entry, span: str) -> float:
    """Substring-based matching: checks if any codebook tokens appear inside the span or vice versa.
    Critical for Chinese where '探针接触不良' in span contains both '探针' and '接触不良' as codebook tokens."""
    if not span:
        return 0.0
    span_lower = span.lower()
    total_tokens = 0
    matched_tokens = 0

    # Check if codebook tokens appear as substrings in the span
    for tok in entry.tok_all:
        # Only check multi-char Chinese tokens (skip pure-ascii short tokens)
        if len(tok) < 2:
            continue
        total_tokens += 1
        if tok in span_lower:
            matched_tokens += 1
        # Also check if span tokens appear in codebook text (reverse direction)
        elif len(tok) > 3 and any(c > '\uffff' for c in tok):
            # For Chinese tokens, also try if the token is contained in any codebook keyword field
            pass

    # Also check span->codebook direction for Chinese: split span by char n-grams
    # and see if codebook tokens are contained in the span
    span_chars = set()
    for ch in span:
        if ch > '\uffff':  # CJK character
            span_chars.add(ch)

    # Collect all Chinese characters from codebook tokens
    cb_chars = set()
    for tok in entry.tok_all:
        for ch in tok:
            if ch > '\uffff':
                cb_chars.add(ch)

    char_overlap = len(span_chars & cb_chars) / max(len(span_chars | cb_chars), 1) if (span_chars or cb_chars) else 0.0

    if total_tokens == 0:
        return char_overlap

    return max(matched_tokens / total_tokens, char_overlap)"}

